import { readFile, writeFile } from "node:fs/promises";
import { dirname, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const scriptDirectory = dirname(fileURLToPath(import.meta.url));
const projectRoot = resolve(scriptDirectory, "..");
const sourcePath = resolve(projectRoot, "brand/tokens.json");
const notesSourcePath = resolve(projectRoot, "brand/notes.md");
const inventorySourcePath = resolve(projectRoot, "docs/brandsources.md");
const publicJsonPath = resolve(projectRoot, "src/brand-tokens.json");
const publicCssPath = resolve(projectRoot, "src/brand-tokens.css");
const publicNotesPath = resolve(projectRoot, "src/brand-notes.md");
const publicInventoryPath = resolve(projectRoot, "src/brandsources.md");

const sourceText = await readFile(sourcePath, "utf8");
const notesText = await readFile(notesSourcePath, "utf8");
const inventoryText = await readFile(inventorySourcePath, "utf8");
const tokens = JSON.parse(sourceText);
const flat = [];
const missingSources = [];

function visit(value, path = []) {
  if (!value || typeof value !== "object" || Array.isArray(value)) return;
  if (Object.prototype.hasOwnProperty.call(value, "$value")) {
    const name = path.join(".");
    flat.push({ name, ...value });
    if (!value.source) missingSources.push(name);
    return;
  }
  for (const [key, child] of Object.entries(value)) {
    if (!key.startsWith("$")) visit(child, [...path, key]);
  }
}

visit(tokens);

if (missingSources.length) {
  throw new Error(`Every token needs a source. Missing: ${missingSources.join(", ")}`);
}

function cssName(name) {
  return `--professionals-${name.replace(/[^a-zA-Z0-9]+/g, "-").toLowerCase()}`;
}

function cssValue(value) {
  if (typeof value === "number") return String(value);
  if (typeof value !== "string") return null;
  const reference = value.match(/^\{(.+)\}$/);
  return reference ? `var(${cssName(reference[1])})` : value;
}

const cssLines = flat
  .map(token => ({ ...token, css: cssValue(token.$value) }))
  .filter(token => token.css !== null)
  .map(token => `  ${cssName(token.name)}: ${token.css};`);

const css = [
  "/* Generated from brand/tokens.json. Do not edit this file directly. */",
  ":root {",
  ...cssLines,
  "}",
  ""
].join("\n");

await writeFile(publicJsonPath, `${JSON.stringify(tokens, null, 2)}\n`);
await writeFile(publicCssPath, css);
// The downloadable copy lives beside brand-tokens.json, not tokens.json.
const publicNotesText = notesText.replace(/\]\(\.\/tokens\.json(?=[#)])/g, "](./brand-tokens.json");
await writeFile(publicNotesPath, publicNotesText);
await writeFile(publicInventoryPath, inventoryText);

console.log(`Published ${flat.length} sourced brand tokens and the supporting notes and inventory.`);
